import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import styles from './Auth.module.css';

export default function Register() {
  const { register } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', username: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await register(form.email, form.username, form.password);
      navigate('/login', {
        state: { message: 'Account created. Sign in to create or join a community group.' },
      });
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed. User may already exist.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.backgroundOrbOne} />
      <div className={styles.backgroundOrbTwo} />

      <div className={styles.shell}>
        <aside className={styles.hero}>
          <div className={styles.brand}>
            <span className={styles.brandMark}>F</span>
            <span className={styles.brandName}>Finbric</span>
          </div>
          <span className={styles.eyebrow}>Get started free</span>
          <h1 className={styles.heroTitle}>Organize your community finances.</h1>
          <p className={styles.heroText}>
            Create an account to start a group, invite members, and manage shared loans, investments, and balances.
          </p>
          <div className={styles.featureList}>
            <div className={styles.featureItem}>
              <span className={`${styles.featureIcon} ${styles.featureIconDebt}`}>🏘️</span>
              <div>
                <p className={styles.featureTitle}>Build your community</p>
                <p className={styles.featureText}>Set up a group for your cooperative, club, or savings circle.</p>
              </div>
            </div>
            <div className={styles.featureItem}>
              <span className={`${styles.featureIcon} ${styles.featureIconInvest}`}>🤝</span>
              <div>
                <p className={styles.featureTitle}>Lend and invest together</p>
                <p className={styles.featureText}>Manage group loans and pooled investments with full visibility.</p>
              </div>
            </div>
            <div className={styles.featureItem}>
              <span className={`${styles.featureIcon} ${styles.featureIconPlan}`}>🔒</span>
              <div>
                <p className={styles.featureTitle}>Trusted member records</p>
                <p className={styles.featureText}>Keep balances and activity transparent for every group member.</p>
              </div>
            </div>
          </div>
        </aside>

        <section className={styles.card}>
          <span className={styles.cardEyebrow}>Create account</span>
          <h2 className={styles.title}>Join Finbric</h2>
          <p className={styles.subtitle}>Set up your profile and start managing community group finances.</p>

          {error && <p className={styles.error}>{error}</p>}

          <form onSubmit={handleSubmit} className={styles.form}>
            <div className={styles.field}>
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="email"
                value={form.email}
                onChange={handleChange}
                placeholder="you@example.com"
                autoComplete="email"
                required
              />
            </div>
            <div className={styles.field}>
              <label htmlFor="username">Username</label>
              <input
                id="username"
                name="username"
                type="text"
                value={form.username}
                onChange={handleChange}
                placeholder="Choose a username"
                autoComplete="username"
                required
              />
            </div>
            <div className={styles.field}>
              <label htmlFor="password">Password</label>
              <input
                id="password"
                name="password"
                type="password"
                value={form.password}
                onChange={handleChange}
                placeholder="Create a strong password"
                autoComplete="new-password"
                required
              />
            </div>
            <button type="submit" className={styles.primaryButton} disabled={loading}>
              {loading ? 'Creating account...' : 'Create account'}
            </button>
          </form>

          <p className={styles.link}>
            Already have an account? <Link to="/login">Sign in</Link>
          </p>
        </section>
      </div>
    </div>
  );
}
